<template><el-card shadow="never" class="settings-card"><template #header><div class="card-header"><div><strong>场景配置</strong><small>管理检测类别、中文映射和可用状态</small></div><el-button type="primary" @click="open()">新增场景</el-button></div></template><el-table :data="items" v-loading="loading" row-key="id"><el-table-column prop="name" label="标识" min-width="140"/><el-table-column prop="display_name" label="名称" min-width="160"/><el-table-column prop="category" label="分类" width="120"/><el-table-column label="类别" width="90"><template #default="{row}">{{row.class_names?.length||0}}</template></el-table-column><el-table-column label="状态" width="90"><template #default="{row}"><el-tag :type="row.is_active?'success':'info'">{{row.is_active?'启用':'停用'}}</el-tag></template></el-table-column><el-table-column label="操作" width="210"><template #default="{row}"><el-button link @click="showDetail(row)">详情</el-button><el-button link type="primary" @click="open(row)">编辑</el-button><el-button link type="danger" :loading="deletingId===row.id" @click="remove(row)">删除</el-button></template></el-table-column><template #empty><el-empty description="暂无检测场景"/></template></el-table>
<el-dialog v-model="dialog" :title="form.id?'编辑场景':'新增场景'" width="640px" :close-on-click-modal="false"><el-form label-position="top"><el-form-item label="场景标识" required><el-input v-model="form.name" :disabled="Boolean(form.id)" placeholder="例如 pcb_inspection"/></el-form-item><el-form-item label="显示名称" required><el-input v-model="form.display_name"/></el-form-item><el-form-item label="分类" required><el-input v-model="form.category"/></el-form-item><el-form-item label="英文类别" required><el-input v-model="form.classNamesText" type="textarea" :rows="3" placeholder="short,open_circuit"/><div class="hint">使用英文逗号分隔；已产生业务记录后，后端禁止修改类别集合。</div></el-form-item><el-form-item label="中文映射"><el-input v-model="form.classNamesCnText" type="textarea" :rows="4" placeholder='{"short":"短路"}'/></el-form-item><el-form-item label="描述"><el-input v-model="form.description" type="textarea" :rows="3"/></el-form-item><el-form-item label="启用"><el-switch v-model="form.is_active"/></el-form-item></el-form><template #footer><el-button :disabled="saving" @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="save">保存</el-button></template></el-dialog>
<el-drawer v-model="detailDrawer" title="场景详情" size="520px"><el-descriptions v-if="detail" :column="1" border><el-descriptions-item label="标识">{{detail.name}}</el-descriptions-item><el-descriptions-item label="名称">{{detail.display_name}}</el-descriptions-item><el-descriptions-item label="分类">{{detail.category}}</el-descriptions-item><el-descriptions-item label="状态">{{detail.is_active?'启用':'停用'}}</el-descriptions-item><el-descriptions-item label="英文类别">{{detail.class_names?.join('、')}}</el-descriptions-item><el-descriptions-item label="中文类别">{{Object.values(detail.class_names_cn||{}).join('、')||'-'}}</el-descriptions-item><el-descriptions-item label="说明">{{detail.description||'-'}}</el-descriptions-item></el-descriptions></el-drawer></el-card></template>
<script setup>
import { onMounted,reactive,ref } from 'vue';import { ElMessage,ElMessageBox } from 'element-plus';import { createScene,deleteScene,getScene,getScenes,updateScene } from '@/api/scenes'
const items=ref([]),loading=ref(false),saving=ref(false),deletingId=ref(null),dialog=ref(false),detailDrawer=ref(false),detail=ref(null);const form=reactive({id:null,name:'',display_name:'',category:'industry',classNamesText:'',classNamesCnText:'{}',description:'',is_active:true})
async function load(){loading.value=true;try{items.value=(await getScenes(true)).items||[]}catch{}finally{loading.value=false}}
function open(row=null){Object.assign(form,row?{id:row.id,name:row.name,display_name:row.display_name,category:row.category,classNamesText:(row.class_names||[]).join(','),classNamesCnText:JSON.stringify(row.class_names_cn||{},null,2),description:row.description||'',is_active:row.is_active}:{id:null,name:'',display_name:'',category:'industry',classNamesText:'',classNamesCnText:'{}',description:'',is_active:true});dialog.value=true}
async function save(){let mapping;try{mapping=JSON.parse(form.classNamesCnText||'{}')}catch{return ElMessage.error('中文映射必须是合法 JSON')}const classes=form.classNamesText.split(',').map(v=>v.trim()).filter(Boolean);if(!form.name.trim()||!form.display_name.trim()||!classes.length)return ElMessage.warning('请填写场景标识、显示名称和缺陷类别');const data={display_name:form.display_name,category:form.category,description:form.description,is_active:form.is_active,class_names:classes,class_names_cn:mapping};saving.value=true;try{form.id?await updateScene(form.id,data):await createScene({name:form.name,...data});ElMessage.success('场景已保存');dialog.value=false;await load()}catch{}finally{saving.value=false}}
async function showDetail(row){detail.value=await getScene(row.id);detailDrawer.value=true}
async function remove(row){try{await ElMessageBox.confirm(`确认删除场景“${row.display_name}”？已被数据集、检测、训练或模型引用时，后端会拒绝删除。`,'删除场景',{type:'warning'});deletingId.value=row.id;await deleteScene(row.id);ElMessage.success('场景已删除');await load()}catch{}finally{deletingId.value=null}}
onMounted(load)
</script>
<style lang="scss" scoped>.settings-card{border-radius:$border-radius-lg}.card-header{display:flex;align-items:center;justify-content:space-between}.card-header strong,.card-header small{display:block}.card-header small{margin-top:4px;color:$text-secondary;font-weight:400}.hint{margin-top:5px;color:$text-secondary;font-size:12px}</style>
